// ============================================================================
// WF-01 -- Normalize
// Maps inbound webhook payloads (GHL workflow webhooks and Close webhooks)
// into the canonical message consumed by the agent service:
//
//   {
//     message_id: string,            // stable id of the inbound message
//     channel:    "sms" | "email",   // Phase 1 = sms; email is Phase 2
//     source:     "close" | "ghl",   // which system delivered the event
//     sender:     string,            // phone number (sms) or email address
//     body:       string,            // message text
//     timestamp:  string             // ISO-8601 of when the message arrived
//   }
//
// SHAPE STATUS: UNVERIFIED. No real captured executions have been seen yet.
// Every field marked [VERIFY] below is a best guess and MUST be checked
// against a real GHL workflow webhook execution and a real Close webhook
// execution before this workflow goes live. Illustrative shapes live in
// n8n/fixtures/ (GHL: ghl_customer_replied.json, Close: close_sms.json).
//
// Contract:
//   - Output 0 (main): one canonical message item per recognised payload.
//   - Output 1 (error): payloads this node could not recognise, routed to
//     the error sink for logging. NEVER throws -- unknown shapes land on
//     output 1, never crash the workflow.
// ============================================================================

const items = $input.all();
const ok = [];   // output 0: canonical messages
const bad = [];  // output 1: unknown shapes

// ---- Shape detectors -------------------------------------------------------
function isCloseWebhook(p) {
  // Close webhooks wrap the payload as { event, object_type, data, ... }. [VERIFY]
  if (!p || typeof p !== 'object') return false;
  return (typeof p.event === 'string' && p.data && typeof p.data === 'object')
      || typeof p.object_type === 'string';
}

function isGHLWorkflowWebhook(p) {
  // GHL workflow webhooks (e.g. the "Customer Replied" workflow) POST the
  // contact object plus message/trigger fields. [VERIFY]
  if (!p || typeof p !== 'object') return false;
  return (p.contact && typeof p.contact === 'object')
      || typeof p.contact_id === 'string'
      || (p.message && typeof p.message === 'object');
}

// ---- Mappers ----------------------------------------------------------------
function mapGHL(p) {
  const contact = p.contact || {};                 // [VERIFY] contact object present?
  const msg = p.message || {};                     // [VERIFY] message object present?
  const rawType = String(msg.type || msg.channel || p.channel || '').toUpperCase(); // [VERIFY]
  const channel = rawType === 'EMAIL' ? 'email' : 'sms'; // default sms; Phase 1 scope. [VERIFY]
  return {
    message_id: String(msg.id || p.message_id || p.event_id || ''), // [VERIFY]
    channel,
    source: 'ghl',
    // Prefer the channel-appropriate identity. [VERIFY]
    sender: channel === 'email'
      ? String(contact.email || msg.from || '')
      : String(contact.phone || contact.phone_number || msg.from || ''),
    body: String(msg.body || msg.text || ''),                       // [VERIFY]
    timestamp: String(msg.date_added || msg.created_at || p.timestamp || new Date().toISOString()), // [VERIFY]
  };
}

function mapClose(p) {
  const data = p.data || {};                        // [VERIFY] payload wrapped in `data`?
  const rawType = String(data.type || data.activity_type || '').toUpperCase(); // [VERIFY]
  const channel = rawType === 'EMAIL' ? 'email' : 'sms'; // [VERIFY]
  const contact = data.contact || {};               // [VERIFY] contact nested under data?
  const phones = Array.isArray(contact.phones) ? contact.phones : []; // [VERIFY]
  const firstPhone = (phones[0] && phones[0].phone) || '';
  return {
    message_id: String(data.id || p.id || ''),      // [VERIFY]
    channel,
    source: 'close',
    sender: channel === 'email'
      ? String(contact.email || data.sender || '')  // [VERIFY]
      : String(firstPhone || contact.phone || data.sender || ''), // [VERIFY]
    body: String(data.text || data.body || ''),     // [VERIFY]
    timestamp: String(data.date_created || data.created_at || p.date_created || new Date().toISOString()), // [VERIFY]
  };
}

// ---- Main -------------------------------------------------------------------
for (const item of items) {
  const p = item.json;
  let canonical = null;
  let shape = 'unknown';

  if (isCloseWebhook(p)) { shape = 'close'; canonical = mapClose(p); }
  else if (isGHLWorkflowWebhook(p)) { shape = 'ghl'; canonical = mapGHL(p); }

  if (canonical && canonical.body && canonical.sender) {
    ok.push({ json: canonical });
  } else {
    bad.push({ json: {
      error: 'unknown_or_incomplete_shape',
      detected_shape: shape,
      hint: 'Compare against n8n/fixtures/*.json and update the mappers above.',
      raw: p,
    }});
  }
}

// Two outputs: [canonical messages, unknown shapes]. Never throws.
return [ok, bad];
